import {schoolSources} from './school-data.js';
import {recordId} from './ids.js';
import {labDefinitions,photoRate,osmosisModel,enzymeRate,energyLevels,punnett,sampleOffspring} from './lab-science.js';
import {escapeHTML as esc,xpFor} from './learning.js';

const initial={photosynthesis:{light:50,co2:50,temperature:25},osmosis:{concentration:50},enzyme:{temperature:35,ph:7},phototropism:{direction:70,progress:0},mendel:{parentA:'Aa',parentB:'Aa'},ecosystem:{initial:10000,efficiency:10}};
const format=n=>Number(n).toLocaleString('vi-VN',{maximumFractionDigits:2});
let svgSerial=0;
function uniqueSVG(svg){const prefix=`lab-illustration-${++svgSerial}-`;return svg.replace(/id="(glass|plant|pea|glow)"/g,(_,id)=>`id="${prefix}${id}"`).replace(/url\(#(glass|plant|pea|glow)\)/g,(_,id)=>`url(#${prefix}${id})`)}
const wrap=(body,label)=>uniqueSVG(`<svg viewBox="0 0 600 400" role="img" aria-label="${label}" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="glass" x1="0" x2="1"><stop stop-color="#a9d8ca" stop-opacity=".08"/><stop offset=".5" stop-color="#cce5d3" stop-opacity=".02"/><stop offset="1" stop-color="#b8dfcf" stop-opacity=".13"/></linearGradient><linearGradient id="plant" x2=".9" y2="1"><stop stop-color="#d3e7a0"/><stop offset="1" stop-color="#527e45"/></linearGradient><radialGradient id="pea"><stop stop-color="#e2ecaf"/><stop offset="1" stop-color="#739f50"/></radialGradient><filter id="glow"><feGaussianBlur stdDeviation="4"/></filter></defs>${body}</svg>`);
function bubbles(rate,x=270,y=270){return Array.from({length:Math.ceil(rate/8)},(_,i)=>`<circle class="svg-bubble" cx="${x+Math.sin(i*4.1)*50}" cy="${y-(i%4)*25}" r="${3+i%4}" fill="#d4eac6" fill-opacity=".15" stroke="#d4eac6" stroke-opacity=".55" style="--bubble-delay:${-i*.37}s;--bubble-duration:${5-rate*.025}s"/>`).join('')}
function photoScene(p){const rate=photoRate(p.light,p.co2,p.temperature);return wrap(`<ellipse cx="300" cy="349" rx="155" ry="17" fill="#000" opacity=".18"/><path d="M170 70v250q0 24 28 24h204q28 0 28-24V70" fill="url(#glass)" stroke="#b3d4bf" stroke-opacity=".45" stroke-width="2"/><ellipse cx="300" cy="70" rx="130" ry="12" fill="none" stroke="#bdddc5" stroke-opacity=".5"/><path d="M172 133q128 16 256 0v187q0 20-26 20H198q-26 0-26-20Z" fill="#689e8833"/><path d="M300 320q-25-65 0-140" fill="none" stroke="#95b768" stroke-width="7"/><path d="M298 245C220 245 222 180 234 170c58 0 75 29 64 75Z" fill="url(#plant)"/><path d="M298 219c1-72 61-74 81-67-4 52-31 76-81 67Z" fill="url(#plant)"/><path d="m238 181 60 64m0-26 66-57" fill="none" stroke="#d9e8ab" stroke-opacity=".5"/>${bubbles(rate)}<g opacity="${.15+p.light/120}"><circle cx="497" cy="65" r="28" fill="#dbe6a4" fill-opacity=".13"/><circle cx="497" cy="65" r="14" fill="#e1e8ae"/><path d="m480 91-64 94m91-91-73 119m50-119-85 91" stroke="#dce9b0" stroke-opacity=".25"/></g><text x="300" y="382" text-anchor="middle" fill="#c2d5b4" font-size="17">Lá nhận ánh sáng · CO₂ được cung cấp</text>`,'Cây thủy sinh minh họa quang hợp với bọt khí thay đổi theo điều kiện')}
function osmosisScene(p){const m=osmosisModel(p.concentration);const dots=Array.from({length:Math.round(p.concentration/2)+4},(_,i)=>`<circle cx="${45+(i*71)%510}" cy="${50+(i*83)%280}" r="3" fill="#cfdbb1" opacity=".35"/>`).join('');return wrap(`${dots}<rect x="157" y="90" width="286" height="244" rx="45" fill="#58784022" stroke="#abc888" stroke-width="10"/><g transform="translate(300 212) scale(${m.scale})"><rect x="-135" y="-112" width="270" height="224" rx="40" fill="#598b6999" stroke="#cee1a1" stroke-width="3"/><ellipse cx="15" cy="-3" rx="79" ry="83" fill="#9dd6b155" stroke="#a9d2b8" stroke-opacity=".6"/><circle cx="-78" cy="31" r="25" fill="#b89ba4"/><circle cx="-82" cy="30" r="9" fill="#7c5b7e"/></g>${m.direction==='balanced'?`<path d="M89 195h45m-45 34h45m-12-42 12 8-12 8m-21 18-12 8 12 8" stroke="#b8d7c7" fill="none" stroke-width="2"/>`:`<g transform="${m.direction==='in'?'translate(600 0) scale(-1 1)':''}"><path class="water-arrow" d="M151 190H60m20-13-20 13 20 13M450 230h90m-20-13 20 13-20 13" fill="none" stroke="#b8d7c7" stroke-width="3"/></g>`}<text x="300" y="44" text-anchor="middle" fill="#d4e4bc" font-size="20">${m.mode}</text><text x="300" y="378" text-anchor="middle" fill="#b9cfaa" font-size="17">Thành tế bào giữ hình dạng · Khối nguyên sinh thay đổi</text>`,'Tế bào thực vật và sự thay đổi khối nguyên sinh khi thẩm thấu')}
function enzymeScene(p){const rate=enzymeRate(p.temperature,p.ph);const points=Array.from({length:81},(_,t)=>`${300+t*3},${285-enzymeRate(t,p.ph)*1.5}`).join(' ');return wrap(`<ellipse cx="165" cy="324" rx="92" ry="13" fill="#000" opacity=".2"/><path d="M92 70v224q0 22 22 22h100q22 0 22-22V70" fill="url(#glass)" stroke="#b8d9bf" stroke-opacity=".55" stroke-width="2"/><ellipse cx="164" cy="70" rx="72" ry="9" stroke="#b8d9bf" stroke-opacity=".55" fill="none"/><path d="M94 151q70 13 140 0v143q0 20-20 20H114q-20 0-20-20Z" fill="#bbbf7833"/><path d="m135 278 23-15 31 12-3 25-36 4Z" fill="#c5b58b"/>${bubbles(rate,166,250)}<text x="165" y="352" text-anchor="middle" fill="#cbdcb3" font-size="17">Mẫu enzyme giả định</text><path d="M295 110v180h254" fill="none" stroke="#afc79c" stroke-opacity=".5"/><polyline points="${points}" fill="none" stroke="#c4dda0" stroke-width="3"/><circle cx="${300+p.temperature*3}" cy="${285-rate*1.5}" r="6" fill="#e8dca5"/><path d="M${300+p.temperature*3} 290V${285-rate*1.5}" stroke="#e8dca5" stroke-dasharray="4 6" opacity=".5"/><text x="305" y="86" fill="#c3d8ac" font-size="17">Hoạt tính tương đối</text><text x="300" y="315" fill="#a7bd97" font-size="15">0°C</text><text x="512" y="315" fill="#a7bd97" font-size="15">80°C</text><text x="418" y="352" text-anchor="middle" fill="#a7bd97" font-size="16">Đường cong minh họa theo nhiệt độ</text>`,'Mẫu enzyme và đồ thị hoạt tính theo nhiệt độ với pH được chọn')}
function plantScene(p){const bend=p.direction/100*(p.progress/10)*105,tipY=295-p.progress*16,tipX=300+bend;const lampX=300+p.direction*1.9;return wrap(`<path d="M${lampX-18} 65 ${tipX-35} ${tipY+8} ${tipX+40} ${tipY+8} ${lampX+18} 65Z" fill="#d1e29b0e"/><circle cx="${lampX}" cy="57" r="20" fill="#e4dfa2"/><circle cx="${lampX}" cy="57" r="35" fill="#d9e6970a"/><path d="M222 315h156l-17 65H239Z" fill="#8d7350"/><path d="M217 311h166v15H217Z" fill="#a58c61"/><ellipse cx="300" cy="311" rx="80" ry="12" fill="#343a23"/><path d="M300 312C300 260 ${tipX} ${tipY+45} ${tipX} ${tipY}" fill="none" stroke="#93b66c" stroke-width="8" stroke-linecap="round"/><path d="M${tipX} ${tipY+25}c-48 8-62-22-65-35 41-9 65 6 65 35Z" fill="url(#plant)"/><path d="M${tipX} ${tipY+11}c37-3 53-29 51-45-38 0-56 15-51 45Z" fill="url(#plant)"/><text x="300" y="34" text-anchor="middle" fill="#b8cda7" font-size="16">Nguồn sáng: ${p.direction< -10?'bên trái':p.direction>10?'bên phải':'ở giữa'}</text>`,'Chồi non phát triển hướng về nguồn sáng qua các giai đoạn minh họa')}
function mendelScene(p,sample){const result=punnett(p.parentA,p.parentB);return wrap(`<text x="300" y="32" text-anchor="middle" fill="#d0e1b5" font-size="23">${p.parentA} × ${p.parentB}</text>${[...p.parentA].map((a,i)=>`<text x="${258+i*108}" y="69" text-anchor="middle" fill="#b7cfa0" font-size="22">${a}</text>`).join('')}${[...p.parentB].map((a,i)=>`<text x="174" y="${130+i*83}" text-anchor="middle" fill="#b7cfa0" font-size="22">${a}</text>`).join('')}${result.cells.map((g,i)=>{const x=208+(i%2)*108,y=83+Math.floor(i/2)*83;return `<rect x="${x}" y="${y}" width="100" height="76" rx="9" fill="${g==='aa'?'#b4a37825':'#a7ce7525'}" stroke="#bdd09d33"/><text x="${x+50}" y="${y+32}" fill="#deebc8" text-anchor="middle" font-size="23">${g}</text><circle cx="${x+50}" cy="${y+55}" r="10" fill="${g==='aa'?'#c4a569':'url(#pea)'}"/>`}).join('')}<text x="300" y="283" text-anchor="middle" fill="#a9c094" font-size="16">${sample?'Mẫu hậu thế vừa gieo':'Mỗi ô là một tổ hợp giao tử có cùng xác suất'}</text>${sample?sample.offspring.map((g,i)=>`<circle cx="${120+(i%10)*40}" cy="${315+Math.floor(i/10)*36}" r="12" fill="${g==='aa'?'#c4a569':'url(#pea)'}"/><text x="${120+(i%10)*40}" y="${319+Math.floor(i/10)*36}" text-anchor="middle" fill="#173420" font-size="9">${g}</text>`).join(''):`<text x="300" y="332" text-anchor="middle" fill="#c5d9ac" font-size="20">Trội ${result.dominant*100}% · Lặn ${result.recessive*100}%</text>`}`,'Bảng Punnett và mẫu cây đậu hậu thế được mô phỏng')}
function ecosystemScene(p){const levels=energyLevels(p.initial,p.efficiency),labels=['Sinh vật sản xuất','Tiêu thụ bậc 1','Tiêu thụ bậc 2','Tiêu thụ bậc 3'],colors=['#628849','#80904f','#a79d62','#b8a57c'];return wrap(`${levels.map((value,i)=>{const width=456-i*101,y=286-i*72;return `<rect x="${300-width/2}" y="${y}" width="${width}" height="61" rx="9" fill="${colors[i]}" fill-opacity=".3" stroke="${colors[i]}"/><text x="300" y="${y+23}" text-anchor="middle" fill="#cbdcb4" font-size="16">${labels[i]}</text><text x="300" y="${y+47}" text-anchor="middle" fill="#e1ebce" font-size="22">${format(value)}</text>`}).join('')}<text x="300" y="385" text-anchor="middle" fill="#a6bd95" font-size="16">Đơn vị năng lượng quy ước · Cùng diện tích và thời gian</text>`,'Tháp năng lượng gồm bốn bậc dinh dưỡng với hiệu suất truyền được chọn')}
const scenes={photosynthesis:photoScene,osmosis:osmosisScene,enzyme:enzymeScene,phototropism:plantScene,mendel:mendelScene,ecosystem:ecosystemScene};
const range=(key,label,min,max,value,unit='',step=1)=>`<div class="experiment-control"><label for="lab-${key}">${label}<output data-output="${key}">${value}${unit}</output></label><input data-lab-control="${key}" id="lab-${key}" type="range" min="${min}" max="${max}" step="${step}" value="${value}" data-unit="${unit}"><div class="range-endpoints"><span>${min}${unit}</span><span>${max}${unit}</span></div></div>`;
function controls(id,p){
 if(id==='photosynthesis')return range('light','Cường độ ánh sáng',0,100,p.light,'%')+range('co2','Mức cung cấp CO₂',0,100,p.co2,'%')+range('temperature','Nhiệt độ mẫu giả định',0,55,p.temperature,'°C');
 if(id==='osmosis')return range('concentration','Chất tan bên ngoài (quy ước)',0,100,p.concentration)+`<p class="control-hint">Bên trong tế bào: mốc 50. So sánh bên ngoài thấp hơn, bằng hoặc cao hơn mốc này.</p>`;
 if(id==='enzyme')return range('temperature','Nhiệt độ',0,80,p.temperature,'°C')+range('ph','pH',2,12,p.ph,'',.5);
 if(id==='phototropism')return range('direction','Hướng chiếu sáng: trái ↔ phải',-100,100,p.direction)+range('progress','Tiến trình sinh trưởng',0,10,p.progress,'',.25)+`<button class="button button-dark" data-lab-action="grow">Cho mầm cây lớn lên <span aria-hidden="true">▷</span></button>`;
 if(id==='mendel')return `<div class="parent-selects">${['A','B'].map(k=>`<label for="parent-${k}">Cây bố/mẹ ${k}<select id="parent-${k}" data-lab-control="parent${k}">${['AA','Aa','aa'].map(g=>`<option ${p['parent'+k]===g?'selected':''}>${g}</option>`).join('')}</select></label>`).join('')}</div><div class="control-hint">A quy định tính trạng trội hoàn toàn. Mỗi ô Punnett có xác suất 25%.</div><button class="button button-dark" data-lab-action="sow">Gieo một mẫu 20 cây <span aria-hidden="true">✳</span></button>`;
 return range('initial','Năng lượng sinh vật sản xuất',1000,20000,p.initial,'',1000)+range('efficiency','Hiệu suất mỗi lần truyền',5,20,p.efficiency,'%');
}
function evaluate(id,p,sample){
 if(id==='photosynthesis'){const rate=photoRate(p.light,p.co2,p.temperature);return {metric:`${rate}%`,label:'Chỉ số quang hợp tương đối',result:`Chỉ số ${rate}%`,conditions:`Ánh sáng ${p.light}%; CO₂ ${p.co2}%; ${p.temperature}°C`,observation:!p.light?'Không có ánh sáng: thêm CO₂ không thay thế được năng lượng ánh sáng.':!p.co2?'Trong mô hình, thiếu CO₂ làm chỉ số về 0 dù có ánh sáng.':rate===100?'Ánh sáng và CO₂ đã bão hòa trong mô hình, nhiệt độ ở đỉnh quy ước. So sánh khi chỉ đổi nhiệt độ.':'Hãy giữ một yếu tố và chỉ thay đổi yếu tố còn lại. Mức thay đổi nào có tác động rõ hơn?'}}
 if(id==='osmosis'){const m=osmosisModel(p.concentration);return {metric:m.mode,label:'Trạng thái môi trường',result:`${m.mode}; chỉ số thể tích tương đối ${m.index}`,conditions:`Nồng độ ngoài ${p.concentration}; mốc trong 50`,observation:m.direction==='out'?'Nước có xu hướng đi ra. Khối nguyên sinh co lại, có thể tách khỏi thành tế bào.':m.direction==='in'?'Nước có xu hướng đi vào, làm tăng sức trương. Thành tế bào giới hạn độ căng.':'Không có dòng nước thuần đáng kể trong mô hình cân bằng này; nước vẫn trao đổi hai chiều.'}}
 if(id==='enzyme'){const rate=enzymeRate(p.temperature,p.ph);return {metric:`${rate}%`,label:'Hoạt tính tương đối',result:`Hoạt tính ${rate}%`,conditions:`Nhiệt độ ${p.temperature}°C; pH ${p.ph}`,observation:p.temperature>=65?'Hoạt tính về 0 do giả định enzyme bị biến tính ở nhiệt độ cao. Đổi điều kiện tương ứng một mẫu mới.':Math.abs(p.ph-7)>2?'pH đang cách xa vùng thuận lợi của enzyme giả định. Giữ nhiệt độ và thử đưa pH về gần 7.':'Thử tăng nhiệt độ dần. Đường cong sẽ không tăng mãi; vị trí đỉnh phụ thuộc enzyme trong thực tế.'}}
 if(id==='phototropism')return {metric:`${p.progress}/10`,label:'Giai đoạn sinh trưởng minh họa',result:`Giai đoạn ${p.progress}/10; chồi hướng ${p.direction< -10?'trái':p.direction>10?'phải':'thẳng'}`,conditions:`Vị trí đèn ${p.direction}; tiến trình ${p.progress}`,observation:p.progress===0?'Mẫu mới bắt đầu với chồi thẳng. Bấm cho cây lớn lên hoặc kéo thanh tiến trình để quan sát sự thay đổi.':'Độ cong tăng dần khi có sinh trưởng không đều. Đây là quá trình sinh trưởng, không phải cây quay tức thời.'};
 if(id==='mendel'){const m=punnett(p.parentA,p.parentB);return {metric:`${m.dominant*100}% : ${m.recessive*100}%`,label:'Tỉ lệ kiểu hình trội : lặn kỳ vọng',conditions:`${p.parentA} × ${p.parentB}`,result:`Kỳ vọng trội ${m.dominant*100}%, lặn ${m.recessive*100}%${sample?`; mẫu 20 cây: AA=${sample.counts.AA}, Aa=${sample.counts.Aa}, aa=${sample.counts.aa}`:''}`,observation:sample?`Mẫu vừa gieo có ${sample.counts.AA+sample.counts.Aa} cây biểu hiện trội và ${sample.counts.aa} cây lặn. Mẫu nhỏ có thể khác tỉ lệ kỳ vọng; thử gieo lại để so sánh.`:'Chọn hai cây bố mẹ, đọc bảng Punnett rồi dự đoán trước khi gieo 20 cây giả lập.'}}
 const levels=energyLevels(p.initial,p.efficiency);return {metric:format(levels[3]),label:'Năng lượng đến tiêu thụ bậc 3',result:`Bốn bậc: ${levels.map(format).join(' → ')}`,conditions:`Đầu vào ${format(p.initial)}; hiệu suất ${p.efficiency}%`,observation:'Năng lượng không truyền nguyên vẹn lên bậc sau. Một phần được dùng cho hoạt động sống, tỏa nhiệt hoặc không được ăn và đồng hóa.'};
}

export function createLabExperience(api){
 let active=null,params=null,sample=null,timer=null,filter='all';
 const isActive=()=>api.getModalType()==='experiment'&&active;
 function catalog(){const list=labDefinitions.filter(d=>filter==='all'||d.grade===Number(filter));document.querySelector('#lab-catalog').innerHTML=list.map((d,i)=>`<article class="experiment-card"><button class="experiment-preview" data-action="experiment" data-id="${d.id}" aria-label="Mở thí nghiệm ${d.title}">${scenes[d.id](initial[d.id])}<span class="experiment-play">${api.icon('play')}</span></button><div class="experiment-card-copy"><div class="experiment-card-meta"><span>LỚP ${d.grade}</span><span>${d.duration}</span></div><span class="experiment-kicker">${d.tag}</span><h2>${d.title}</h2><p>${d.description}</p><button class="text-button" data-action="experiment" data-id="${d.id}">Vào trạm khám phá ${api.icon('arrow-up-right')}</button></div></article>`).join('');document.querySelector('#lab-catalog-count').textContent=`${list.length} trạm tương tác`;document.querySelectorAll('[data-lab-grade]').forEach(b=>{const selected=b.dataset.labGrade===filter;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected))})}
 function rows(){const s=api.getState();return active.id==='photosynthesis'?s.trials.map((t,i)=>({conditions:`Ánh sáng ${t.light}%; CO₂ ${t.co2}%; ${Number.isFinite(t.temperature)?t.temperature+"°C":"nhiệt độ chưa mô phỏng (bản cũ)"}`,result:`Chỉ số ${t.rate}%`})):s.labRuns.filter(r=>r.labId===active.id)}
 function renderHistory(){const list=rows();document.querySelector('#experiment-history').innerHTML=list.length?`<div class="experiment-history-heading"><h3>Nhật ký so sánh</h3><span>${list.length} lần thử đã lưu</span></div><div class="report-table-wrap"><table class="trial-table"><thead><tr><th>Lần</th><th>Điều kiện</th><th>Kết quả mô hình</th></tr></thead><tbody>${list.map((r,i)=>`<tr><td>${i+1}</td><td>${esc(r.conditions)}</td><td>${esc(r.result)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="experiment-empty">Ghi lần thử đầu tiên, thay đổi một yếu tố rồi ghi thêm để so sánh.</div>'}
 function refresh(){if(!isActive())return;const value=evaluate(active.id,params,sample);document.querySelector('#experiment-visual').innerHTML=scenes[active.id](params,sample);document.querySelector('#experiment-metric').textContent=value.metric;document.querySelector('#experiment-metric-label').textContent=value.label;document.querySelector('#experiment-observation').textContent=value.observation;document.querySelectorAll('[data-lab-control]').forEach(el=>{const out=document.querySelector(`[data-output="${el.dataset.labControl}"]`);if(out)out.textContent=params[el.dataset.labControl]+(el.dataset.unit||'')});return value}
 function open(id='photosynthesis'){const def=labDefinitions.find(d=>d.id===id);if(!def)return;stop();active=def;params={...initial[id]};sample=null;api.showDialog(def.title,`PHÒNG THÍ NGHIỆM / LỚP ${def.grade}`,`<div class="experiment-steps"><span>01 · Đặt câu hỏi</span><span>02 · Tự thay đổi</span><span>03 · So sánh & giải thích</span></div><p class="experiment-question">${def.question}</p><div class="experiment-prediction"><label for="experiment-prediction">Dự đoán trước khi thử</label><textarea id="experiment-prediction" rows="2" maxlength="1000" placeholder="Nếu thay đổi… thì… vì…"></textarea></div><div class="experiment-layout"><div><div class="experiment-stage" id="experiment-visual"></div><div class="experiment-observation" id="experiment-observation" role="status"></div></div><div class="experiment-settings"><span class="experiment-kicker">ĐIỀU KIỆN DO BẠN CHỌN</span>${controls(id,params)}<div class="experiment-reading"><span id="experiment-metric-label"></span><strong id="experiment-metric"></strong></div><button class="button button-dark" data-lab-action="record">Ghi kết quả lần thử ${api.icon('plus')}</button><p class="control-hint">Giữ một điều kiện cố định để so sánh có ý nghĩa.</p></div></div><div id="experiment-history"></div><div class="modal-actions"><button class="button button-dark" data-lab-action="note">Lưu phát hiện vào sổ tay ${api.icon('notebook')}</button><button class="text-button" data-action="lesson" data-id="${def.lesson}">Đọc bài liên quan ${api.icon('arrow-right')}</button></div><details class="experiment-assumptions"><summary>Giả định mô hình & nguồn tham khảo</summary><p>${def.limits}</p><a href="${schoolSources[def.grade].url}" target="_blank" rel="noopener">SGK lớp ${def.grade} · NXBGDVN ↗</a><br><a href="${def.source}" target="_blank" rel="noopener">Đọc nguồn OpenStax Biology 2e ↗</a></details>`,'experiment');refresh();renderHistory()}
 function record(){const s=api.getState(),oldXP=xpFor(s),r=refresh();if(active.id==='photosynthesis'){s.trials.push({light:params.light,co2:params.co2,temperature:params.temperature,rate:photoRate(params.light,params.co2,params.temperature)});s.trials=s.trials.slice(-20)}else{s.labRuns.push({id:recordId(),labId:active.id,conditions:r.conditions,result:r.result,date:new Date().toISOString()});s.labRuns=s.labRuns.slice(-100)}if(!s.completedLabs.includes(active.id))s.completedLabs.push(active.id);api.trackActivity?.();api.persist();renderHistory();api.toast(xpFor(s)>oldXP?'Trạm khám phá mới được ghi dấu · +20 XP!':'Đã ghi kết quả. Thử thay đổi một yếu tố để so sánh.')}
 function note(){const list=rows();if(!list.length){api.toast('Hãy ghi ít nhất một lần thử trước khi lưu phát hiện.');return}api.addNote(`Thí nghiệm: ${active.title}`,list.map((r,i)=>`Lần ${i+1}: ${r.conditions}\n→ ${r.result}`).join('\n\n')+`\n\nCâu hỏi: ${active.question}\nDự đoán trước khi thử: ${document.querySelector('#experiment-prediction')?.value||'Chưa ghi'}\nĐiều mình phát hiện:\n\nMô hình minh họa, không phải số liệu thực nghiệm.\nNguồn: ${active.source}`);api.openNotebook();api.toast('Đã lưu các lần thử vào sổ tay.')}
 function stop(){if(timer)clearInterval(timer);timer=null}
 document.addEventListener('input',e=>{const el=e.target.closest('[data-lab-control]');if(!el||!isActive())return;const key=el.dataset.labControl;params[key]=el.tagName==='SELECT'?el.value:Number(el.value);if(active.id==='mendel')sample=null;if(active.id==='phototropism'&&key==='direction'){stop();params.progress=0;document.querySelector('#lab-progress').value=0}refresh()});
 document.addEventListener('click',e=>{const filterButton=e.target.closest('[data-lab-grade]');if(filterButton){filter=filterButton.dataset.labGrade;catalog();return}const b=e.target.closest('[data-lab-action]');if(!b||!isActive())return;const action=b.dataset.labAction;if(action==='record')record();if(action==='note')note();if(action==='sow'){sample=sampleOffspring(params.parentA,params.parentB);refresh()}if(action==='grow'){if(timer){stop();b.innerHTML='Tiếp tục cho cây lớn lên ▷';return}if(params.progress>=10)params.progress=0;b.textContent='Tạm dừng sinh trưởng Ⅱ';timer=setInterval(()=>{if(!isActive()){stop();return}params.progress=Math.min(10,params.progress+.25);document.querySelector('#lab-progress').value=params.progress;refresh();if(params.progress>=10){stop();b.textContent='Quan sát lại từ đầu ▷'}},200)}});
 catalog();return {open,stop,renderCatalog:catalog};
}
